"""

from __future__ import annotations

from typing import List


# --------------------------------------------------------------------------
# Core digit utilities
# --------------------------------------------------------------------------
def decimal_digits(n: int) -> List[int]:
    """Return the base-10 digits of n (little-endian), matching Nat.digits 10 n.

    By convention digits(0) == []. For n > 0 the last entry is the nonzero
    leading digit.
    """
    if n < 0:
        raise ValueError("n must be a natural number")
    if n == 0:
        return []
    out: List[int] = []
    while n > 0:
        out.append(n % 10)
        n //= 10
    return out


def digit_power_sum(n: int) -> int:
    """Sum of decimal digits of n each raised to the power L = number of digits.

    This is exactly the right-fold S_{L(n)}(digits_10(n)) from the paper.
    """
    ds = decimal_digits(n)
    length = len(ds)
    return sum(d ** length for d in ds)


def is_narcissistic(n: int) -> bool:
    """Decide whether n is a narcissistic (Armstrong) number.

    Mirrors the decidable predicate IsNarcissistic: n equals the sum of its
    digits each raised to the power of the digit count. (n == 0 has no digits,
    so the empty sum is 0, making 0 narcissistic.)
    """
    return n == digit_power_sum(n)


